state.awards??=[];
const feedbackDeck=AssessmentCore.createSoundDeck();
const rewardNames=['Искра любопытства','Солнечная пятёрка','Звезда открытий','Комета знаний','Легенда алфавита'];
function ruCount(n,one,few,many){const a=n%100,b=n%10;return n+' '+(a>=11&&a<=14?many:b===1?one:b>=2&&b<=4?few:many);}
const rewardSymbols=['✦','☀','★','✧','♛'];
playFeedback=function(correct){
 try{const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return;effectContext??=new AudioCtx();effectContext.resume();const ctx=effectContext,t=ctx.currentTime,variant=feedbackDeck.next(correct);
 const positive=[[0,4,7],[7,12,16],[0,7,12,16],[4,7,12],[0,12,7,16],[7,9,12,19]];
 const retry=[[0,-3],[-2,-5,0],[2,-2],[0,-5,-2],[3,0,-3],[0,-2,-5]];
 const notes=(correct?positive:retry)[variant],base=correct?440:294,spacing=correct?.085:.1;
 notes.forEach((semitone,i)=>{const start=t+i*spacing,osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=variant%2?'triangle':'sine';osc.frequency.setValueAtTime(base*2**(semitone/12),start);if(!correct)osc.frequency.exponentialRampToValueAtTime(base*2**((semitone-1)/12),start+.16);gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(correct?.055:.035,start+.012);gain.gain.exponentialRampToValueAtTime(.001,start+.23);osc.connect(gain);gain.connect(ctx.destination);osc.start(start);osc.stop(start+.26);});
 }catch{}
};
function medal(index,small=false){return `<span class="medal medal-${index%5} ${small?'medal-small':''}" aria-hidden="true"><span class="medal-ribbon"></span><span class="medal-face"><span>${rewardSymbols[index%5]}</span></span></span>`;}
function rewardCollection(){return `<section class="reward-collection" id="rewards"><div class="section-head"><div><span class="eyebrow">МАЛЕНЬКИЕ ПОБЕДЫ · БОЛЬШОЕ СОКРОВИЩЕ</span><h2>Твои награды <span class="reward-count">${state.awards.length}</span></h2><p>Пять букв подряд без ошибок — новая звезда в коллекции.</p></div><span class="reward-cabinet-spark">✦</span></div><div class="reward-shelf">${state.awards.length?state.awards.slice().reverse().map(a=>`<button class="reward-badge" onclick="showSavedReward('${a.id}')">${medal(a.style,true)}<b>${escapeHTML(a.name)}</b><span>${a.letters.map(l=>l.toUpperCase()).join(' · ')}</span><small>${new Date(a.at).toLocaleDateString('ru-RU')}</small></button>`).join(''):[0,1,2].map((i)=>`<div class="reward-badge reward-locked">${medal(i,true)}<b>${i===0?'Первая искра':i===1?'Следующее открытие':'Ещё одна звезда'}</b><span>${i===0?'Твоя первая серия из 5 букв':'Скоро в твоей коллекции'}</span><small>Имя + звук · без ошибок</small></div>`).join('')}</div></section>`;}
function diagnosticProgress(){const p=AssessmentCore.progress(quiz);return `<section class="alphabet-dashboard" id="alphabetDashboard"><div class="alphabet-dashboard-head"><div><span class="eyebrow">ТВОЁ ПУТЕШЕСТВИЕ A → Z</span><h3>${p.completed} <small>из 26 букв</small> <span class="progress-percent">${p.percent}%</span></h3></div><div class="remaining-copy">До финиша <b>${ruCount(p.remainingLetters,'буква','буквы','букв')}</b><small>${ruCount(p.remainingQuestions,'задание','задания','заданий')}: имя и звук</small></div></div><div class="alphabet-meter" role="progressbar" aria-label="Прогресс диагностики" aria-valuemin="0" aria-valuemax="52" aria-valuenow="${p.answered}"><div style="width:${p.percent}%"></div><span style="left:clamp(10px,${p.percent}%,calc(100% - 10px))">✦</span></div><div class="alphabet-map">${p.letters.map((d,i)=>{const current=i===Math.floor(quiz.index/2),label=d.problem?`${d.letter.toUpperCase()}: были ошибки${d.name.errors.length?' в названии':''}${d.sound.errors.length?' в звуке':''}`:d.complete?`${d.letter.toUpperCase()}: без ошибок`:`${d.letter.toUpperCase()}: ${current?'сейчас проверяем':'впереди'}`;return `<button class="alphabet-stop ${d.problem?'has-problem':d.complete?'is-clean':current?'is-current':''}" aria-label="${label}" onclick="showLetterProgress('${d.letter}')"><b>${d.letter.toUpperCase()}</b><span class="letter-skill-dots"><i class="${d.name.errors.length?'dot-problem':d.name.completed?'dot-clean':''}"></i><i class="${d.sound.errors.length?'dot-problem':d.sound.completed?'dot-clean':''}"></i></span>${d.problem?'<span class="problem-mark">!</span>':d.complete?'<span class="complete-mark">✓</span>':''}</button>`;}).join('')}</div><div class="alphabet-legend"><span><i class="legend-clean"></i> Без ошибок</span><span><i class="legend-problem"></i> Повторим</span><span><i class="legend-current"></i> Сейчас</span><span>Две точки: имя · звук</span></div><div class="streak-tracker"><div class="streak-icon">✦</div><div><b>${p.streak?`${ruCount(p.streak,'буква','буквы','букв')} подряд без ошибок`:'Соберём серию из пяти букв?'}</b><small>Считаем и название, и звук — с первой попытки.</small></div><div class="streak-gems" aria-label="До следующей награды ${p.nextReward} букв">${Array.from({length:5},(_,i)=>`<span class="${i<(p.streak>0&&p.streak%5===0?5:p.streak%5)?'gem-earned':''}">✦</span>`).join('')}</div><span class="streak-count">Ещё ${p.nextReward} до награды</span></div></section>`;}
function refreshDiagnosticProgress(){const dashboard=document.getElementById('alphabetDashboard');if(dashboard)dashboard.outerHTML=diagnosticProgress();}
function showLetterProgress(l){const d=AssessmentCore.progress(quiz).letters.find(x=>x.letter===l);const modeLabel=x=>x.errors.length?`${x.errors.length} ${pluralAttempts(x.errors.length)}. Выбирал: ${x.errors.map(e=>e.answer.toUpperCase()).join(', ')}.`:x.completed?'С первой попытки.':'Пока не проверено.';showModal(`<div class="eyebrow">БУКВА НА ТВОЁМ МАРШРУТЕ</div><h2>${l.toUpperCase()} <span style="opacity:.4">${l}</span></h2><p><b>Название:</b> ${modeLabel(d.name)}</p><p><b>Звук:</b> ${modeLabel(d.sound)}</p><button class="primary" onclick="modal.close()">Продолжаем →</button>`);}
function collectMilestones(){const p=AssessmentCore.progress(quiz),fresh=[];for(const milestone of p.milestones){if(state.awards.some(a=>a.id===milestone.key))continue;const index=state.awards.length,award={id:milestone.key,name:rewardNames[index%5],style:index%5,letters:milestone.letters,at:new Date().toISOString(),runStartedAt:quiz.startedAt};state.awards.push(award);fresh.push(award);}if(fresh.length)persist();return fresh;}
function showReward(award,continuation){
 stopDiagnosticAudio();modal.classList.add('reward-dialog');const confetti=Array.from({length:35},(_,i)=>`<i style="--i:${i};--x:${(i*31)%100}%;--delay:${(i%7)*.08}s;--hue:${[40,150,265,20,185][i%5]}"></i>`).join('');
 showModal(`<div class="reward-celebration"><div class="reward-confetti" aria-hidden="true">${confetti}</div><div class="reward-rays" aria-hidden="true"></div><div class="reward-floating-star one">✦</div><div class="reward-floating-star two">✧</div><span class="eyebrow">НОВАЯ НАГРАДА В ТВОЕЙ КОЛЛЕКЦИИ</span>${medal(award.style)}<h2>${escapeHTML(award.name)}</h2><p><b>Пять букв подряд без ошибок!</b><br>Ты узнал и названия, и звуки с первой попытки.</p><div class="award-letter-chips">${award.letters.map(l=>`<span>${l.toUpperCase()}</span>`).join('')}</div><button class="primary" onclick="modal.close()">${continuation?'Забрать и продолжить':'Здорово!'} <span>✦</span></button><small>Награда уже сохранена внизу, в твоей коллекции.</small></div>`);
 modal.addEventListener('close',()=>{modal.classList.remove('reward-dialog');continuation?.();},{once:true});
}
function showSavedReward(id){const award=state.awards.find(a=>a.id===id);if(award)showReward(award);}
// Decorate page containers; the letter-card design stays in diagnostic.css.
const worldNavigate=navigate;
navigate=function(next){worldNavigate(next);if(['home','results','path','worlds'].includes(next))app.insertAdjacentHTML('beforeend',rewardCollection());};
const studioRender=renderDiagnostic;
renderDiagnostic=function(){studioRender();const trail=document.querySelector('.alphabet-trail');if(trail){trail.outerHTML=diagnosticProgress();document.querySelector('.letter-studio').insertAdjacentHTML('beforeend',rewardCollection());}};
// Commit each milestone before the animation, then move on only when it closes.
answerDiagnostic=function(answer,button){
 const q=quiz?.items[quiz.index];if(!q||view!=='assessment')return;const result=AssessmentCore.answer(quiz,answer,heardQuestion===AssessmentCore.key(q));
 if(!result.accepted){if(!heardQuestion){toast('Сначала послушай название или звук.');document.querySelector('.listen-orb')?.focus();}return;}
 state.pendingQuiz=quiz;persist();stopDiagnosticAudio();playFeedback(result.correct);refreshDiagnosticProgress();
 if(!result.correct){button.disabled=true;button.classList.add('dimmed');document.getElementById('diagnosticFeedback').textContent='Эта буква отдыхает. Посмотри на другие — попробуй ещё!';return;}
 document.querySelectorAll('.toy-answer').forEach(b=>b.disabled=true);button.classList.add('celebrate');document.getElementById('diagnosticFeedback').textContent=q.mode==='name'?'Да! Ты нашёл букву по её имени.':'Получилось! Это её звук.';
 const fresh=collectMilestones(),current=quiz;
 const advance=()=>{if(view!=='assessment'||quiz!==current)return;quiz.index++;state.pendingQuiz=quiz;persist();if(quiz.index<quiz.items.length)renderDiagnostic();else{finishDiagnostic();app.insertAdjacentHTML('beforeend',rewardCollection());}};
 diagnosticTimer=setTimeout(()=>{if(view!=='assessment'||quiz!==current)return;if(fresh.length)showReward(fresh[0],advance);else advance();},950);
};
